package ca.brtalgo.uberwatcher;
import android.Manifest;import android.app.*;import android.content.*;import android.content.pm.PackageManager;import android.os.Build;
public final class AlertHelper{public static final String CHANNEL_ID="uber_opportunity_alerts";private AlertHelper(){}public static void createChannel(Context c){if(Build.VERSION.SDK_INT<26)return;NotificationManager n=c.getSystemService(NotificationManager.class);if(n!=null)n.createNotificationChannel(new NotificationChannel(CHANNEL_ID,"Uber opportunity alerts",NotificationManager.IMPORTANCE_HIGH));}public static void notify(Context c,String t,String b){createChannel(c);if(Build.VERSION.SDK_INT>=33&&c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)return;PendingIntent p=PendingIntent.getActivity(c,1,new Intent(c,MainActivity.class),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,CHANNEL_ID).setSmallIcon(android.R.drawable.ic_dialog_info).setContentTitle(t).setContentText(b).setStyle(new Notification.BigTextStyle().bigText(b)).setPriority(Notification.PRIORITY_MAX).setAutoCancel(true).setContentIntent(p).build();NotificationManager m=(NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE);if(m!=null)m.notify(4001,n);}}
